const fs = require("node:fs");
const values = fs.readFileSync(0, "utf8").trim().split(/\s+/).map(Number);
const [n, k] = values;
const a = values.slice(2);

let low = 0;
let high = 0;
for (let i = 0; i < n; i++) {
    low = Math.max(low, a[i]);
    high += a[i];
}
while (low < high) {
    let middle = low + Math.floor((high - low) / 2);
    let groups = 1;
    let load = 0;
    for (let i = 0; i < n; i++) {
        if (load + a[i] > middle) {
            groups++;
            load = 0;
        }
        load += a[i];
    }
    if (groups <= k) {
        high = middle;
    } else {
        low = middle + 1;
    }
}
console.log(low);

