package main

import (
    "bufio"
    "fmt"
    "os"
)

func main() {
    in := bufio.NewReader(os.Stdin)
    out := bufio.NewWriter(os.Stdout)
    defer out.Flush()
    var n, k int
    if _, err := fmt.Fscan(in, &n, &k); err != nil { return }
    a := []int{}
    for {
        var value int
        if _, err := fmt.Fscan(in, &value); err != nil { break }
        a = append(a, value)
    }
    _ = k
    low := 0;
    high := 0;
    for i := 0; i < n; i++ {
        low = max(low, a[i]);
        high += a[i];
    }
    for (low < high) {
        middle := low + (high - low) / 2;
        groups := 1;
        load := 0;
        for i := 0; i < n; i++ {
            if (load + a[i] > middle) {
                groups++;
                load = 0;
            }
            load += a[i];
        }
        if (groups <= k) {
            high = middle;
        } else {
            low = middle + 1;
        }
    }
    fmt.Fprintln(out, low);
}

